    $q=db()->prepare('SELECT * FROM users WHERE email=? AND active=1'); $q->execute([$loginEmail]); $row=$q->fetch();
    if($row) { $pwOk=password_verify($loginPw,$row['password_hash']); } else { password_verify($loginPw,'$2y$12$AyU3/45YBW4nSyz65IBCW.vMNuI87wdsDq0qcwoAd10IvtQD4SbYm'); $pwOk=false; }
    if($pwOk) { rate_limit_clear('login_email',$loginEmail);
        if(otp_enabled()) { $days=max(1,min(30,(int)setting('otp_remember_days','5'))); $activity=strtotime((string)($row['last_activity_at']??''))?:0; $verified=!empty($row['email_verified_at']); if(!$verified || !$activity || time()-$activity>($days*86400)) { if(!send_otp($row['email'],'login',['user_id'=>(int)$row['id']])) {flash('Could not send a verification code. Please try again in 60 seconds.','error');redirect(url('login'));} flash('For account security, enter the verification code sent to your email.'); redirect(url('verify')); } }
        session_regenerate_id(true); $_SESSION['uid']=$row['id']; db()->prepare('UPDATE users SET last_login=?,last_activity_at=? WHERE id=?')->execute([date('c'),date('c'),$row['id']]); audit('login'); redirect(url('dashboard'));
