    if($purpose==='register') { $payload=json_decode((string)$row['payload'],true)?:[];try{$role=(int)db()->query("SELECT id FROM roles WHERE name='user'")->fetchColumn();db()->prepare('INSERT INTO users(name,email,password_hash,role_id,active,created_at,email_verified_at,otp_verified_at,phone,company,department) VALUES(?,?,?,?,1,?,?,?,?,?,?)')->execute([$payload['name'],$row['email'],$payload['password_hash'],$role,date('c'),date('c'),date('c'),$payload['phone']??null,$payload['company']??null,$payload['department']??null]);flash('Email verified and account created. You can now sign in.');redirect(url('login'));}catch(Throwable $e){flash('Could not create account. The email may already be registered.','error');redirect(url('register'));} }
