    if($purpose==='profile_email') { $payload=json_decode((string)$row['payload'],true)?:[]; $uid=(int)($payload['user_id']??0); try { db()->prepare('UPDATE users SET email=?,email_verified_at=?,otp_verified_at=? WHERE id=?')->execute([$row['email'],date('c'),date('c'),$uid]); flash('Your email address has been updated and verified.'); redirect(url('profile')); } catch(Throwable $e) { flash('Could not update the email address. It may already be in use.','error'); redirect(url('profile')); } }
    redirect(url('login'));
