if($page==='resend_otp' && $_SERVER['REQUEST_METHOD']==='POST') { $purpose=$_SESSION['otp_purpose']??''; $id=$_SESSION['otp_challenge']??''; $q=db()->prepare('SELECT email,payload FROM otp_challenges WHERE id=? AND session_hash=?');$q->execute([$id,hash('sha256',session_id())]);$old=$q->fetch();if($old && send_otp($old['email'],$purpose,json_decode((string)$old['payload'],true)?:[])) flash('A new verification code has been sent.'); else flash('Please wait 60 seconds before requesting another code.','error');redirect(url('verify')); }
if($page==='guest_start' && $_SERVER['REQUEST_METHOD']==='POST') { if(setting('allow_guest','0')!=='1'){http_response_code(403);exit('Guest submissions are disabled.');} $name=trim($_POST['guest_name']??'');$email=strtolower(trim($_POST['guest_email']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Enter a name and valid email address.','error');redirect(url('new'));} $existing=db()->prepare('SELECT id FROM users WHERE email=?');$existing->execute([$email]);if($existing->fetchColumn()){flash('An account already exists for this email address. Please sign in with your existing account to submit your ticket.','error');redirect(url('login'));} if(otp_enabled()){if(!send_otp($email,'guest',['name'=>$name])){flash('Could not send a code, or please wait 60 seconds before requesting another.','error');redirect(url('new'));}flash('A verification code has been sent.');redirect(url('verify'));} $_SESSION['guest_verified']=['email'=>$email,'name'=>$name,'verified_at'=>time()];redirect(url('new',['step'=>'ticket']));}
if($page==='logout') { if($_SERVER['REQUEST_METHOD']!=='POST') redirect(url($u?'dashboard':'login')); if($u) audit('logout'); $_SESSION=[]; session_destroy(); redirect(url('login')); }
if($page==='submit' && $_SERVER['REQUEST_METHOD']==='POST') {
    $u=current_user(); $guest=!$u;
    if(!$guest && !has_permission('tickets.create',$u) && !has_permission('tickets.assign',$u)){http_response_code(403);exit('You do not have permission to create tickets.');}
    if($guest && setting('allow_guest','0')!=='1') { http_response_code(403); exit('Guest submissions are disabled.'); }
    if($guest && otp_enabled()) { $gv=$_SESSION['guest_verified']??null; if(!$gv || (int)$gv['verified_at']<time()-1800 || strtolower(trim($_POST['guest_email']??''))!==$gv['email'] || trim($_POST['guest_name']??'')!==$gv['name']) { http_response_code(403); exit('Verify your email before submitting a ticket.'); } }
    $subject=trim($_POST['subject']??''); $desc=trim($_POST['description']??'');
    $isStaff=$u && has_permission('tickets.assign',$u);
    $assignedUserId=null;
    if($isStaff && !empty($_POST['assigned_user_id'])) {
        $candidate=(int)$_POST['assigned_user_id'];
        $aq=db()->prepare('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.active=1');
        $aq->execute([$candidate]); $candidateUser=$aq->fetch();
        if($candidateUser && has_permission('tickets.assign',$candidateUser)) $assignedUserId=$candidate;
    }
    $guestName=trim($_POST['guest_name']??''); $guestEmail=strtolower(trim($_POST['guest_email']??'')); $guestPhone=trim($_POST['guest_phone']??''); $guestCompany=trim($_POST['guest_company']??''); $guestDepartment=trim($_POST['guest_department']??'');
    if($guest && filter_var($guestEmail,FILTER_VALIDATE_EMAIL)) { $registered=db()->prepare('SELECT id FROM users WHERE email=?'); $registered->execute([$guestEmail]); if($registered->fetchColumn()) { flash('An account already exists for this email address. Please sign in or use account registration.','error'); redirect(url('login')); } }
    if($subject===''||$desc===''||($guest&&($guestName===''||!filter_var($guestEmail,FILTER_VALIDATE_EMAIL)||$guestPhone===''))) { flash('Complete the required fields using a valid email address.','error'); redirect(url('new')); }
    $pdo=db(); $pdo->beginTransaction();
    try {
        $uid=$guest?null:(int)$u['id'];
        $no='HD-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3))); $status=(int)$pdo->query("SELECT id FROM statuses WHERE name='Open' AND active=1 LIMIT 1")->fetchColumn(); if(!$status) $status=(int)$pdo->query('SELECT id FROM statuses WHERE active=1 ORDER BY id LIMIT 1')->fetchColumn(); $priority=(int)$pdo->query("SELECT id FROM priorities WHERE name='Normal'")->fetchColumn();
        if(!$status || !$priority) throw new RuntimeException('Ticket status or priority defaults are missing.');
        $categoryId=(int)($_POST['category_id']??0); if($categoryId>0) { $cq=$pdo->prepare('SELECT id FROM categories WHERE id=? AND active=1'); $cq->execute([$categoryId]); if(!$cq->fetchColumn()) $categoryId=0; }
        $groupId=null; if($isStaff && !empty($_POST['group_id'])) { $gq=$pdo->prepare('SELECT id FROM groups WHERE id=?'); $gq->execute([(int)$_POST['group_id']]); if($gq->fetchColumn()) $groupId=(int)$_POST['group_id']; }
        $q=$pdo->prepare('INSERT INTO tickets(ticket_no,user_id,subject,description,category_id,priority_id,status_id,group_id,assigned_user_id,created_at,updated_at,guest_name,guest_email,guest_phone,guest_company,guest_department) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
        $q->execute([$no,$uid,$subject,$desc,$categoryId?:null,$priority,$status,$groupId,$assignedUserId,date('c'),date('c'),$guest?$guestName:null,$guest?$guestEmail:null,$guest?$guestPhone:null,$guest?$guestCompany:null,$guest?$guestDepartment:null]); $id=(int)$pdo->lastInsertId();
        if(isset($_FILES['attachment']) && $_FILES['attachment']['error']!==UPLOAD_ERR_NO_FILE) save_attachment($_FILES['attachment'],$id,null,$uid);
        $pdo->commit();
    } catch(Throwable $e) {
        if($pdo->inTransaction()) $pdo->rollBack();
        error_log('[HelpDesk v'.app_version().'] Ticket submission failed: '.$e->getMessage());
        http_response_code(500); exit('The ticket could not be submitted. Please contact support and provide the time of the error.');
    }
    try { $t=ticket_by_id($id); notify_event('ticket_created',$t,'A new support request has been submitted.'); audit('ticket_created',$no); } 
    catch(Throwable $e) { error_log('[HelpDesk v'.app_version().'] Ticket notification/audit failed for '.$no.': '.$e->getMessage()); }
    flash('Ticket '.$no.' was submitted. '.($guest?'Keep your ticket number for reference.':'')); redirect($guest?url('login'):url('ticket',['id'=>$id]));
}
if($page==='update_ticket' && $_SERVER['REQUEST_METHOD']==='POST') {
    $u=require_login(); $id=(int)($_POST['id']??0); $t=ticket_by_id($id);
    if(!$t||!can_view_ticket($u,$t)){http_response_code(403);exit('Forbidden');}
    $tech=has_permission('tickets.edit',$u) || has_permission('tickets.manage',$u); $pdo=db();
    $oldStatus=(int)$t['status_id']; $oldAssigned=(int)($t['assigned_user_id']??0); $oldGroup=(int)($t['group_id']??0);
    $comment=trim((string)($_POST['comment']??'')); if($comment!=='' && !has_permission('tickets.reply',$u) && !has_permission('tickets.internal_note',$u)){http_response_code(403);exit('You do not have permission to reply to tickets.');} if($comment!=='' && !empty($_POST['is_internal']) && !has_permission('tickets.internal_note',$u)){http_response_code(403);exit('You do not have permission to add internal notes.');} $internal=has_permission('tickets.internal_note',$u)&&!empty($_POST['is_internal'])?1:0;
    $notifyRequester=!empty($_POST['notify_requester']) && !$internal;
    $changes=[];
    if($tech) {
        $subject=trim((string)($_POST['subject']??$t['subject'])); $description=trim((string)($_POST['description']??$t['description']));
        $priority=(int)($_POST['priority_id']??$t['priority_id']); $category=(int)($_POST['category_id']??($t['category_id']??0));
        $status=has_permission('tickets.change_status',$u)?(int)($_POST['status_id']??$t['status_id']):(int)$t['status_id']; $priority=has_permission('tickets.change_priority',$u)?$priority:(int)$t['priority_id']; $group=has_permission('tickets.assign',$u)&&array_key_exists('group_id',$_POST)?((int)$_POST['group_id']?:null):($t['group_id']?:null); $assigned=has_permission('tickets.assign',$u)&&array_key_exists('assigned_user_id',$_POST)?((int)$_POST['assigned_user_id']?:null):($t['assigned_user_id']?:null);
        $valid=$pdo->prepare('SELECT id FROM statuses WHERE id=? AND (active=1 OR id=?)'); $valid->execute([$status,$oldStatus]); if(!$valid->fetchColumn()) { flash('Choose an active ticket status.','error'); redirect(url('ticket',['id'=>$id])); }
        $valid=$pdo->prepare('SELECT id FROM priorities WHERE id=?'); $valid->execute([$priority]); if(!$valid->fetchColumn()) $priority=(int)$t['priority_id'];
        if($category>0){$valid=$pdo->prepare('SELECT id FROM categories WHERE id=?');$valid->execute([$category]);if(!$valid->fetchColumn())$category=(int)($t['category_id']??0);} else $category=0;
        if($assigned){$valid=$pdo->prepare('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.active=1');$valid->execute([$assigned]);$candidateUser=$valid->fetch();if(!$candidateUser || !has_permission('tickets.assign',$candidateUser))$assigned=null;}
        if($subject==='') $subject=$t['subject']; if($description==='') $description=$t['description'];
        if($subject!==$t['subject'])$changes[]='Subject updated';
        if($description!==$t['description'])$changes[]='Description updated';
        if($priority!==(int)$t['priority_id'])$changes[]='Priority changed to '.($pdo->query('SELECT name FROM priorities WHERE id='.(int)$priority)->fetchColumn()?:'updated');
        if($category!==(int)($t['category_id']??0))$changes[]='Category updated';
        if($status!==$oldStatus){$sq=$pdo->prepare('SELECT name FROM statuses WHERE id=?');$sq->execute([$status]);$newStatus=(string)$sq->fetchColumn();$changes[]='Status changed to '.$newStatus;}
        if((int)$assigned!==$oldAssigned)$changes[]='Assignment changed';
        $resolvedId=(int)$pdo->query("SELECT id FROM statuses WHERE name='Resolved' LIMIT 1")->fetchColumn();
        $resolvedAt=($resolvedId && $status===$resolvedId)?($t['resolved_at']?:date('c')):null;
        $pdo->prepare('UPDATE tickets SET subject=?,description=?,priority_id=?,category_id=?,status_id=?,group_id=?,assigned_user_id=?,updated_at=?,resolved_at=? WHERE id=?')->execute([$subject,$description,$priority,$category?:null,$status,$group,$assigned,date('c'),$resolvedAt,$id]);
    }
    if($comment!=='') {
        $pdo->prepare('INSERT INTO ticket_comments(ticket_id,user_id,body,is_internal,created_at) VALUES(?,?,?,?,?)')->execute([$id,$u['id'],$comment,$internal,date('c')]);
        $pdo->prepare('UPDATE tickets SET updated_at=? WHERE id=?')->execute([date('c'),$id]);
        $changes[]=$internal?'Internal note added':'Public reply added';
        if(!$internal) $notifyRequester=!empty($_POST['notify_requester']);
    }
    if($changes){$pdo->prepare('INSERT INTO ticket_history(ticket_id,user_id,action,details,created_at) VALUES(?,?,?,?,?)')->execute([$id,$u['id'],'ticket_updated',implode('; ',$changes),date('c')]);}
    $updated=ticket_by_id($id);
    if($notifyRequester && ($comment!=='' || $changes)) {
        $mailText='Your support request has been updated.';
        if($comment!=='' && !$internal) $mailText.=' Support reply: '.$comment;
        elseif($changes) $mailText.=' '.implode('. ',$changes).'.';
        if($oldStatus!==(int)$updated['status_id'] && $updated['status_name']==='Resolved') notify_event('ticket_resolved',$updated,$mailText);
        else notify_event('ticket_updated',$updated,$mailText);
    }
    if($tech && ((int)($updated['assigned_user_id']??0)!==$oldAssigned || (int)($updated['group_id']??0)!==$oldGroup)) notify_event('ticket_assigned',$updated,'A support request has been assigned to you or your team.');
    if($tech && $oldStatus!==(int)$updated['status_id']) { audit('ticket_status_changed',$updated['ticket_no'].' => '.$updated['status_name']); }
    audit('ticket_updated',$updated['ticket_no']); flash('Ticket updated.'); redirect(url('ticket',['id'=>$id]));
}
if($page==='admin_assign_ticket' && $_SERVER['REQUEST_METHOD']==='POST') {
    $admin=require_permission('tickets.assign');
    $id=(int)($_POST['id']??0);
    $assigned=(int)($_POST['assigned_user_id']??0);
    $ticket=ticket_by_id($id);
    if(!$ticket || !can_view_ticket($admin,$ticket)) { http_response_code(404); exit('Ticket not found.'); }
    if($assigned>0) {
        $check=db()->prepare('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND u.active=1');
        $check->execute([$assigned]); $assignee=$check->fetch();
        if(!$assignee || !has_permission('tickets.assign',$assignee)) { flash('Select an active support technician.','error'); redirect(url('tickets')); }
    }
    $oldAssigned=(int)($ticket['assigned_user_id']??0);
    db()->prepare('UPDATE tickets SET assigned_user_id=?,updated_at=? WHERE id=?')->execute([$assigned?:null,date('c'),$id]);
    $updated=ticket_by_id($id);
    if($oldAssigned!==$assigned) {
        notify_event('ticket_assigned',$updated,'A support request has been assigned to you.');
        audit('ticket_assigned',$updated['ticket_no'].' => '.($updated['assigned_name']??'Unassigned'));
        flash('Ticket assignment updated.');
    } else { flash('No assignment change was made.'); }
    redirect(url('tickets'));
}
if($page==='save_status' && $_SERVER['REQUEST_METHOD']==='POST') { require_permission('statuses.manage'); $id=(int)($_POST['id']??0); $name=trim((string)($_POST['name']??'')); if($name===''){flash('Status name is required.','error');redirect(url('statuses'));} $active=isset($_POST['active'])?1:0; if(!$active){$q=db()->prepare('SELECT COUNT(*) FROM statuses WHERE active=1 AND id<>?');$q->execute([$id]);if((int)$q->fetchColumn()===0){flash('At least one active ticket status must remain.','error');redirect(url('statuses'));}} try { if($id) db()->prepare('UPDATE statuses SET name=?,active=? WHERE id=?')->execute([$name,$active,$id]); else db()->prepare('INSERT INTO statuses(name,active) VALUES(?,?)')->execute([$name,isset($_POST['active'])?1:0]); audit('status_saved',$name); flash('Ticket status saved.'); } catch(Throwable $e){flash('Could not save status. Status names must be unique.','error');} redirect(url('statuses')); }
if($page==='disable_status' && $_SERVER['REQUEST_METHOD']==='POST') { require_permission('statuses.manage'); $id=(int)($_POST['id']??0); $q=db()->prepare('SELECT COUNT(*) FROM statuses WHERE active=1 AND id<>?');$q->execute([$id]);if((int)$q->fetchColumn()===0){flash('At least one active ticket status must remain.','error');redirect(url('statuses'));} $count=db()->prepare('SELECT COUNT(*) FROM tickets WHERE status_id=?');$count->execute([$id]); if((int)$count->fetchColumn()>0){db()->prepare('UPDATE statuses SET active=0 WHERE id=?')->execute([$id]);flash('Status disabled. Existing tickets keep this status.');}else{db()->prepare('UPDATE statuses SET active=0 WHERE id=?')->execute([$id]);flash('Status disabled.');} redirect(url('statuses')); }
if($page==='save_settings' && $_SERVER['REQUEST_METHOD']==='POST') {
    require_permission('settings.manage'); $section=$_POST['section']??'general';
    $map=[
      'email'=>['mail_from_name','mail_from','notify_ticket_created','notify_ticket_assigned','notify_ticket_updated','notify_ticket_resolved','email_footer','reply_to'],
      'general'=>['app_name','allow_guest','theme','brand_color','contact_email'],
      'security'=>['otp_enabled','otp_remember_days','login_max_attempts','login_lockout_minutes'],
      'templates'=>['template_ticket_created_subject','template_ticket_created_body','template_ticket_assigned_subject','template_ticket_assigned_body','template_ticket_updated_subject','template_ticket_updated_body','template_ticket_resolved_subject','template_ticket_resolved_body']
    ];
    foreach(($map[$section]??[]) as $k){$v=trim((string)($_POST[$k]??'')); if(in_array($k,['otp_remember_days'],true))$v=(string)max(1,min(30,(int)$v)); if($k==='login_max_attempts')$v=(string)max(3,min(20,(int)$v)); if($k==='login_lockout_minutes')$v=(string)max(1,min(240,(int)$v)); if(in_array($k,['allow_guest','otp_enabled','notify_ticket_created','notify_ticket_assigned','notify_ticket_updated','notify_ticket_resolved'],true))$v=isset($_POST[$k])?'1':'0'; db()->prepare('INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)')->execute([$k,$v]);}
    if($section==='general') {
        if(!empty($_POST['remove_brand_logo'])) { $old=setting('brand_logo',''); if($old!=='' && str_starts_with($old,'public/uploads/')) { $f=__DIR__.'/'.$old; if(is_file($f)) @unlink($f); } db()->prepare("DELETE FROM settings WHERE key='brand_logo'")->execute(); }
        if(isset($_FILES['brand_logo_file']) && $_FILES['brand_logo_file']['error']!==UPLOAD_ERR_NO_FILE) {
            $f=$_FILES['brand_logo_file']; if($f['error']!==UPLOAD_ERR_OK) { flash('Logo upload failed. Check PHP upload_max_filesize and post_max_size settings.','error'); redirect(url('settings')); }
            $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); $types=['image/png'=>'png','image/jpeg'=>'jpg','image/gif'=>'gif','image/webp'=>'webp'];
            if(!isset($types[$mime])) { flash('Upload a PNG, JPG, GIF, or WebP logo.','error'); redirect(url('settings')); }
            $dir=__DIR__.'/public/uploads'; if(!is_dir($dir) && !mkdir($dir,0755,true) && !is_dir($dir)) throw new RuntimeException('Could not create logo upload directory.');
            $name='logo-'.bin2hex(random_bytes(12)).'.'.$types[$mime]; if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name)) { flash('Could not save the uploaded logo.','error'); redirect(url('settings')); }
            $oldLogo=setting('brand_logo',''); db()->prepare('INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)')->execute(['brand_logo','public/uploads/'.$name]);
            if($oldLogo!=='' && str_starts_with($oldLogo,'public/uploads/') && $oldLogo!=='public/uploads/'.$name) { $oldPath=__DIR__.'/'.$oldLogo; if(is_file($oldPath)) @unlink($oldPath); }
        }
    }
