,company=?,department=?,role_id=?,active=?,password_hash=?,email_verified_at=CASE WHEN email<>? THEN NULL ELSE email_verified_at END WHERE id=?')->execute([$name,$email,$phone,$company,$department,$role,$active,password_hash($_POST['password'],PASSWORD_DEFAULT),$email,$id]); else db()->prepare('UPDATE users SET name=?,email=?,phone=?,company=?,department=?,role_id=?,active=?,email_verified_at=CASE WHEN email<>? THEN NULL ELSE email_verified_at END WHERE id=?')->execute([$name,$email,$phone,$company,$department,$role,$active,$email,$id]); } else { $pw=$_POST['password']??''; if(strlen($pw)<12) throw new RuntimeException('New user passwords must be at least 12 characters.'); db()->prepare('INSERT INTO users(name,email,password_hash,role_id,active,created_at,phone,company,department) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$role,$active,date('c'),$phone,$company,$department]); $id=(int)db()->lastInsertId(); } if(has_permission('roles.manage',$actor)){db()->prepare('DELETE FROM user_roles WHERE user_id=?')->execute([$id]); $directRoleIds=array_unique(array_merge([$role],array_map('intval',($_POST['direct_roles']??[])))); if(!is_admin($actor)){$directRoleIds=array_values(array_filter($directRoleIds,function($rid) use($actor){return actor_can_assign_role($actor,(int)$rid);}));} foreach($directRoleIds as $drid){db()->prepare('INSERT OR IGNORE INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$id,(int)$drid]);}} elseif($isNewUser){db()->prepare('INSERT OR IGNORE INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$id,$role]);} if(has_permission('groups.manage_members',$actor)){db()->prepare('DELETE FROM user_groups WHERE user_id=?')->execute([$id]); db()->prepare('DELETE FROM group_members WHERE user_id=?')->execute([$id]); foreach(($_POST['groups']??[]) as $gid){db()->prepare('INSERT OR IGNORE INTO user_groups(user_id,group_id) VALUES(?,?)')->execute([$id,(int)$gid]);db()->prepare('INSERT OR IGNORE INTO group_members(group_id,user_id) VALUES(?,?)')->execute([(int)$gid,$id]);}} clear_permission_cache(); audit('user_saved',$email); flash('User saved.'); } catch(Throwable $e){flash($e->getMessage(),'error');} redirect(url('users')); }
