    $targetAdmin=db()->prepare("SELECT COUNT(*) FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.name='admin'");$targetAdmin->execute([$id]);if((int)$targetAdmin->fetchColumn()>0){$activeAdmins=(int)db()->query("SELECT COUNT(DISTINCT u.id) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.active=1 AND r.name='admin'")->fetchColumn();if(!is_admin($admin)||$activeAdmins<=1){flash('System Administrator accounts are protected. Another active System Administrator must remain.','error');redirect(url('users'));}}
    try {
        $pdo->beginTransaction();
