        $pdo->prepare('UPDATE ticket_comments SET user_id=NULL WHERE user_id=?')->execute([$id]); $pdo->prepare('UPDATE ticket_attachments SET uploaded_by=NULL WHERE uploaded_by=?')->execute([$id]);
