function save_attachment(array $f,int $ticketId,?int $commentId,?int $uid): void { global $config; if($f['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Upload failed. Check PHP upload_max_filesize and post_max_size settings.'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'])?:'application/octet-stream'; $allowed=['image/jpeg','image/png','image/gif','image/webp','application/pdf','text/plain','application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']; if(!in_array($mime,$allowed,true)) throw new RuntimeException('This attachment type is not allowed.'); $stored=bin2hex(random_bytes(20)); if(!move_uploaded_file($f['tmp_name'],$config['upload_dir'].'/'.$stored)) throw new RuntimeException('Could not store attachment.'); db()->prepare('INSERT INTO ticket_attachments(ticket_id,comment_id,original_name,stored_name,mime_type,size,uploaded_by,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$ticketId,$commentId,basename($f['name']),$stored,$mime,$f['size'],$uid,date('c')]); }

