if($page==='dashboard') { render_header('Dashboard',$u); $allTickets=has_permission('tickets.view_all',$u); $teamTickets=has_permission('tickets.view_group',$u)||has_permission('tickets.manage',$u); $uid=(int)$u['id']; $where=$allTickets?'1=1':($teamTickets?'(t.assigned_user_id='.$uid.' OR t.group_id IN (SELECT group_id FROM user_groups WHERE user_id='.$uid.')'.(has_permission('tickets.view_own',$u)?' OR t.user_id='.$uid:'').')':(has_permission('tickets.view_own',$u)?'t.user_id='.$uid:'0=1')); $params=[]; $filters=[]; foreach(['status_id','priority_id','category_id','group_id','assigned_user_id'] as $key){if(isset($_GET[$key]) && $_GET[$key]!=='' && ctype_digit((string)$_GET[$key])){$filters[]='t.'.$key.'=?';$params[]=(int)$_GET[$key];}} foreach(['from'=>'substr(t.created_at,1,10)>=?','to'=>'substr(t.created_at,1,10)<=?'] as $key=>$expr){if(!empty($_GET[$key]) && preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)$_GET[$key])){$filters[]=$expr;$params[]=$_GET[$key];}} if(!empty($_GET['q'])){$filters[]='(t.ticket_no LIKE ? OR t.subject LIKE ?)';$params[]='%'.trim($_GET['q']).'%';$params[]='%'.trim($_GET['q']).'%';} if($filters)$where.=' AND '.implode(' AND ',$filters); $statusRows=db()->query('SELECT id,name FROM statuses WHERE active=1 ORDER BY id')->fetchAll(); $counts=[]; foreach($statusRows as $sr){$q=db()->prepare('SELECT COUNT(*) FROM tickets t WHERE '.$where.' AND t.status_id=?');$q->execute(array_merge($params,[$sr['id']]));$counts[$sr['name']]=(int)$q->fetchColumn();} $sql='SELECT t.*,st.name status_name,p.name priority_name,COALESCE(t.guest_name,u.name) user_name,au.name assigned_name FROM tickets t JOIN statuses st ON st.id=t.status_id JOIN priorities p ON p.id=t.priority_id LEFT JOIN users u ON u.id=t.user_id LEFT JOIN users au ON au.id=t.assigned_user_id WHERE '.$where.' ORDER BY t.updated_at DESC LIMIT 50'; $q=db()->prepare($sql);$q->execute($params);$recent=$q->fetchAll(); $max=max(1,max($counts?:[1])); ?><div class="stats-grid"><?php foreach($statusRows as $sr): $sn=$sr['name']; ?><div class="stat-card"><span><?=h($sn)?></span><strong><?=$counts[$sn]??0?></strong><small>Tickets</small></div><?php endforeach; ?></div><div class="section-heading"><div><h2>Ticket queue</h2><p class="muted">Filter tickets by status, priority, category, group, technician, date, or keyword.</p></div><a class="btn primary" href="<?=url('new')?>">＋ New ticket</a></div><details class="panel filter-details"><summary>Show / hide ticket filters</summary><div class="filter-inner"><form method="get" class="filter-form"><input type="hidden" name="page" value="dashboard"><label>Search<input name="q" value="<?=h($_GET['q']??'')?>" placeholder="Ticket or subject"></label><?php foreach(['status_id'=>'statuses','priority_id'=>'priorities','category_id'=>'categories','group_id'=>'groups','assigned_user_id'=>'users'] as $field=>$table): ?><label><?=h(ucwords(str_replace('_',' ',str_replace('_id','',$field))))?><select name="<?=$field?>"><option value="">All</option><?php $opts=$table==='users'?users_with_permission('tickets.assign'):db()->query('SELECT id,name FROM '.$table.' ORDER BY name')->fetchAll();foreach($opts as $opt): ?><option value="<?=$opt['id']?>" <?=((string)($_GET[$field]??'')===(string)$opt['id'])?'selected':''?>><?=h($opt['name'])?></option><?php endforeach; ?></select></label><?php endforeach; ?><label>Created from<input type="date" name="from" value="<?=h($_GET['from']??'')?>"></label><label>Created to<input type="date" name="to" value="<?=h($_GET['to']??'')?>"></label><button class="btn primary">Apply filters</button><a class="btn secondary" href="<?=url('dashboard')?>">Clear</a></form></div></details><div class="panel table-panel spaced"><table><thead><tr><th>Ticket</th><th>Subject</th><th>Status</th><th>Priority</th><th>Assigned to</th><th>Updated</th></tr></thead><tbody><?php if(!$recent): ?><tr><td colspan="6" class="empty">No tickets match these filters.</td></tr><?php else: foreach($recent as $t) render_ticket_row($t); endif; ?></tbody></table></div><?php render_footer(); exit; }
if($page==='tickets') { render_header('Tickets',$u); $allTickets=has_permission('tickets.view_all',$u); $teamTickets=has_permission('tickets.view_group',$u)||has_permission('tickets.manage',$u); $tech=$allTickets||$teamTickets; $admin=has_permission('tickets.assign',$u); $scope=$_GET['scope']??''; $uid=(int)$u['id']; $where=$allTickets?'1=1':($teamTickets?'(t.assigned_user_id='.$uid.' OR t.group_id IN (SELECT group_id FROM user_groups WHERE user_id='.$uid.')'.(has_permission('tickets.view_own',$u)?' OR t.user_id='.$uid:'').')':(has_permission('tickets.view_own',$u)?'t.user_id='.$uid:'0=1')); if($scope==='assigned'&&$tech)$where='t.assigned_user_id='.$uid; $rows=db()->query('SELECT t.*,st.name status_name,p.name priority_name,COALESCE(t.guest_name,u.name) user_name,au.name assigned_name FROM tickets t JOIN statuses st ON st.id=t.status_id JOIN priorities p ON p.id=t.priority_id LEFT JOIN users u ON u.id=t.user_id LEFT JOIN users au ON au.id=t.assigned_user_id WHERE '.$where.' ORDER BY t.updated_at DESC')->fetchAll(); $assignees=$admin?users_with_permission('tickets.assign'):[]; ?><div class="section-heading"><div><p class="muted"><?=count($rows)?> support requests</p><?php if($admin): ?><p class="muted tiny">Assign technicians directly from this list.</p><?php endif; ?></div><a class="btn primary" href="<?=url('new')?>">＋ New ticket</a></div><div class="panel table-panel"><table><thead><tr><th>Ticket</th><th>Subject</th><th>Status</th><th>Priority</th><th>Assigned to</th><?php if($admin): ?><th>Change assignment</th><?php endif; ?><th>Updated</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="<?= $admin?'7':'6' ?>" class="empty">No tickets found.</td></tr><?php else: foreach($rows as $t): ?><tr><td><a class="ticket-number" href="<?=url('ticket',['id'=>$t['id']])?>"><?=h($t['ticket_no'])?></a></td><td><a class="table-title" href="<?=url('ticket',['id'=>$t['id']])?>"><?=h($t['subject'])?></a><small><?=h($t['user_name']??'')?></small></td><td><span class="status status-<?=strtolower(str_replace(' ','-',$t['status_name']))?>"><?=h($t['status_name'])?></span></td><td><?=h($t['priority_name'])?></td><td><?=h($t['assigned_name']??'Unassigned')?></td><?php if($admin): ?><td><form method="post" action="<?=url('admin_assign_ticket')?>" class="inline-assign"><?=csrf_field()?><input type="hidden" name="id" value="<?=$t['id']?>"><select name="assigned_user_id"><option value="0">Unassigned</option><?php foreach($assignees as $a): ?><option value="<?=$a['id']?>" <?=((int)$t['assigned_user_id']===(int)$a['id'])?'selected':''?>><?=h($a['name'])?></option><?php endforeach; ?></select><button class="btn secondary small">Save</button></form></td><?php endif; ?><td class="muted"><?=h(date('M j, Y',strtotime($t['updated_at'])))?></td></tr><?php endforeach; endif; ?></tbody></table></div><?php render_footer(); exit; }
if($page==='ticket') { render_header('Ticket details',$u); $id=(int)($_GET['id']??0); $t=ticket_by_id($id); if(!$t||!can_view_ticket($u,$t)){http_response_code(404);echo '<div class="panel">Ticket not found.</div>';render_footer();exit;} $tech=has_permission('tickets.edit',$u)||has_permission('tickets.manage',$u); $canSeeInternal=has_permission('tickets.internal_note',$u); $comments=db()->prepare('SELECT c.*,u.name FROM ticket_comments c LEFT JOIN users u ON u.id=c.user_id WHERE c.ticket_id=? AND (c.is_internal=0 OR ?) ORDER BY c.created_at'); $comments->execute([$id,$canSeeInternal?1:0]); $comments=$comments->fetchAll(); $hist=db()->prepare('SELECT h.*,u.name FROM ticket_history h LEFT JOIN users u ON u.id=h.user_id WHERE h.ticket_id=? ORDER BY h.created_at DESC');$hist->execute([$id]);$history=$hist->fetchAll(); $atts=db()->prepare('SELECT * FROM ticket_attachments WHERE ticket_id=?');$atts->execute([$id]);$atts=$atts->fetchAll(); ?><div class="ticket-head"><div><div class="ticket-number"><?=h($t['ticket_no'])?></div><h2><?=h($t['subject'])?></h2><p class="muted">Submitted by <?=h($t['user_name'])?> · <?=h(date('M j, Y g:i A',strtotime($t['created_at'])))?></p></div><span class="status status-<?=strtolower(str_replace(' ','-',$t['status_name']))?>"><?=h($t['status_name'])?></span></div><div class="ticket-grid"><div class="ticket-main"><div class="panel description"><h3>Request description</h3><p><?=nl2br(h($t['description']))?></p><?php if($atts): ?><div class="attachment-list"><b>Attachments</b><?php foreach($atts as $a): ?><a href="<?=url('attachment',['id'=>$a['id']])?>">↧ <?=h($a['original_name'])?></a><?php endforeach; ?></div><?php endif; ?></div><?php if($tech): ?><div class="panel form-panel"><h3>Edit ticket</h3><form method="post" action="<?=url('update_ticket')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Subject<input name="subject" value="<?=h($t['subject'])?>" required></label><label>Description<textarea name="description" rows="5" required><?=h($t['description'])?></textarea></label><div class="form-row"><label>Priority<select name="priority_id"><?php foreach(db()->query('SELECT * FROM priorities ORDER BY id') as $p): ?><option value="<?=$p['id']?>" <?=$p['id']==$t['priority_id']?'selected':''?>><?=h($p['name'])?></option><?php endforeach; ?></select></label><label>Category<select name="category_id"><option value="0">Uncategorized</option><?php foreach(db()->query('SELECT * FROM categories WHERE active=1 OR id='.(int)($t['category_id']??0).' ORDER BY name') as $c): ?><option value="<?=$c['id']?>" <?=$c['id']==$t['category_id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach; ?></select></label></div><div class="form-row"><label>Status<select name="status_id"><?php foreach(db()->query('SELECT * FROM statuses WHERE active=1 OR id='.(int)$t['status_id'].' ORDER BY id') as $st): ?><option value="<?=$st['id']?>" <?=$st['id']==$t['status_id']?'selected':''?>><?=h($st['name'])?></option><?php endforeach; ?></select></label><label>Group<select name="group_id"><option value="">Unassigned</option><?php foreach(db()->query('SELECT * FROM groups ORDER BY name') as $g): ?><option value="<?=$g['id']?>" <?=$g['id']==$t['group_id']?'selected':''?>><?=h($g['name'])?></option><?php endforeach; ?></select></label></div><label>Assigned technician<select name="assigned_user_id"><option value="0">Unassigned</option><?php foreach(users_with_permission('tickets.assign') as $a): ?><option value="<?=$a['id']?>" <?=$a['id']==$t['assigned_user_id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach; ?></select></label><label class="check"><input type="checkbox" name="notify_requester" value="1" checked> Email the end user about these changes</label><button class="btn primary">Save ticket changes</button></form></div><?php endif; ?><div class="panel conversation"><h3>Conversation and notes</h3><?php foreach($comments as $c): ?><div class="comment"><div class="comment-top"><b><?=h($c['name']??'Former user')?></b><span><?=h(date('M j, g:i A',strtotime($c['created_at'])))?></span><?php if($c['is_internal']): ?><em>Internal note</em><?php endif; ?></div><p><?=nl2br(h($c['body']))?></p></div><?php endforeach; if(!$comments): ?><p class="muted">No replies or notes yet.</p><?php endif; ?><form method="post" action="<?=url('update_ticket')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label><?=$tech?'Add a reply or internal note':'Add a reply'?><textarea name="comment" rows="4" placeholder="Write a message..."></textarea></label><?php if($tech): ?><label class="check"><input type="checkbox" name="is_internal" value="1"> Internal note (not visible to requester)</label><label class="check"><input type="checkbox" name="notify_requester" value="1" checked> Email this reply to the end user</label><?php endif; ?><button class="btn primary">Post update</button></form></div><?php if($tech && $history): ?><div class="panel conversation"><h3>Ticket activity</h3><?php foreach($history as $hrow): ?><div class="comment"><div class="comment-top"><b><?=h($hrow['name']??'System')?></b><span><?=h(date('M j, Y g:i A',strtotime($hrow['created_at'])))?></span></div><p><?=h($hrow['details'])?></p></div><?php endforeach; ?></div><?php endif; ?></div><aside class="ticket-side"><div class="panel"><h3>Ticket properties</h3><div class="property"><small>Priority</small><b><?=h($t['priority_name'])?></b></div><div class="property"><small>Category</small><b><?=h((string)($t['category_id']?db()->query('SELECT name FROM categories WHERE id='.(int)$t['category_id'])->fetchColumn():'Uncategorized'))?></b></div><div class="property"><small>Group</small><b><?=h($t['group_name']??'Unassigned')?></b></div><div class="property"><small>Assigned to</small><b><?=h($t['assigned_name']??'Unassigned')?></b></div><?php if($tech): ?><hr><h3>Requester contact</h3><div class="property"><small>Email</small><b><?=h($t['user_email']??'')?></b></div><?php if(!empty($t['guest_phone']) || !empty($t['phone'])): ?><div class="property"><small>Phone</small><b><?=h($t['user_phone']??'')?></b></div><?php endif; ?><?php if(!empty($t['guest_company']) || !empty($t['company'])): ?><div class="property"><small>Company</small><b><?=h($t['user_company']??'')?></b></div><?php endif; ?><?php if(!empty($t['guest_department']) || !empty($t['department'])): ?><div class="property"><small>Department</small><b><?=h($t['user_department']??'')?></b></div><?php endif; ?><?php endif; ?><div class="property"><small>Last updated</small><b><?=h(date('M j, Y g:i A',strtotime($t['updated_at'])))?></b></div></div></aside></div><?php render_footer(); exit; }
if($page==='users') { require_permission('users.manage'); render_header('Users',$u); $users=db()->query('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.name')->fetchAll(); $editId=(int)($_GET['edit']??0); $editUser=null; if($editId){$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$editId]);$editUser=$q->fetch()?:null;} $selectedUserGroups=[];$selectedUserRoles=[];$effectivePermissions=[]; if($editUser){$q=db()->prepare('SELECT group_id FROM user_groups WHERE user_id=?');$q->execute([$editUser['id']]);$selectedUserGroups=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=db()->prepare('SELECT role_id FROM user_roles WHERE user_id=?');$q->execute([$editUser['id']]);$selectedUserRoles=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=db()->prepare("SELECT DISTINCT p.permission_key,p.description,r.name role_name,'Direct role' source FROM user_roles ur JOIN roles r ON r.id=ur.role_id JOIN role_permissions rp ON rp.role_id=r.id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=? UNION SELECT DISTINCT p.permission_key,p.description,r.name role_name,'Group: '||g.name source FROM user_groups ug JOIN groups g ON g.id=ug.group_id JOIN group_roles gr ON gr.group_id=g.id JOIN roles r ON r.id=gr.role_id JOIN role_permissions rp ON rp.role_id=r.id JOIN permissions p ON p.id=rp.permission_id WHERE ug.user_id=? ORDER BY permission_key");$q->execute([$editUser['id'],$editUser['id']]);$effectivePermissions=$q->fetchAll();} ?><div class="section-heading"><div><p class="muted">Manage end users and support staff. Users can belong to multiple groups.</p></div></div><div class="panel form-panel"><h2><?=$editUser?'Edit user':'Create user'?></h2><form method="post" action="<?=url('save_user')?>"><?=csrf_field()?> <input type="hidden" name="id" value="<?=h((string)($editUser['id']??''))?>"><div class="form-row"><label>Name<input name="name" value="<?=h($editUser['name']??'')?>" required></label><label>Email<input type="email" name="email" value="<?=h($editUser['email']??'')?>" required></label><label>Contact phone<input name="phone" value="<?=h($editUser['phone']??'')?>"></label><label>Company / organization<input name="company" value="<?=h($editUser['company']??'')?>"></label><label>Department<input name="department" value="<?=h($editUser['department']??'')?>"></label><?php if(has_permission('roles.manage',$u)): ?><label>Role<select name="role_id"><?php foreach(db()->query('SELECT * FROM roles') as $r): ?><option value="<?=$r['id']?>" <?=($editUser['role_id']??4)==$r['id']?'selected':''?>><?=h(ucfirst($r['name']))?></option><?php endforeach; ?></select></label><label>Additional direct roles <small>Permissions from all selected roles are combined.</small></label><div class="member-checks"><?php foreach(db()->query("SELECT * FROM roles WHERE name<>'admin' ORDER BY name") as $r): ?><label class="check"><input type="checkbox" name="direct_roles[]" value="<?=$r['id']?>" <?=((int)($editUser['role_id']??0)!==(int)$r['id'] && in_array((int)$r['id'],$selectedUserRoles,true))?'checked':''?>> <?=h(ucfirst($r['name']))?></label><?php endforeach; ?></div><?php endif; ?><label>Password<input type="password" name="password" minlength="12" <?=$editUser?'':'required'?> placeholder="<?=$editUser?'Leave blank to keep current password':'12 characters minimum'?>"></label></div><?php if(has_permission('groups.manage_members',$u)): ?><label>Groups</label><div class="member-checks"><?php foreach(db()->query('SELECT * FROM groups ORDER BY name') as $ug): ?><label class="check"><input type="checkbox" name="groups[]" value="<?=$ug['id']?>" <?=in_array((int)$ug['id'],$selectedUserGroups,true)?'checked':''?>> <?=h($ug['name'])?></label><?php endforeach; ?></div><?php endif; ?><?php if($editUser): ?><details class="panel form-panel spaced"><summary><b>Effective permissions</b> <small class="muted">What this user can do and where each permission comes from</small></summary><?php if($effectivePermissions): ?><div class="table-panel"><table><thead><tr><th>Permission</th><th>Granted by</th><th>Source</th></tr></thead><tbody><?php foreach($effectivePermissions as $ep): ?><tr><td><?=h($ep['permission_key'])?></td><td><?=h(ucfirst($ep['role_name']))?></td><td><?=h($ep['source'])?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No permissions are currently assigned.</p><?php endif; ?></details><?php endif; ?><label class="check"><input type="checkbox" name="active" <?=(!$editUser || $editUser['active'])?'checked':''?>> Account active</label><button class="btn primary"><?=$editUser?'Save changes':'Create user'?></button></form></div><div class="panel table-panel spaced"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>State</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $x): ?><tr><td><b><?=h($x['name'])?></b></td><td><?=h($x['email'])?></td><td><?=h(ucfirst($x['role_name']))?></td><td><?=$x['active']?'Active':'Disabled'?></td><td><?=h(date('M j, Y',strtotime($x['created_at'])))?></td><td><a href="<?=url('users',['edit'=>$x['id']])?>">Edit</a> <?php if((int)$x['id']!==(int)$u['id'] && has_permission('users.delete',$u)): ?><form method="post" action="<?=url('delete_user')?>" style="display:inline" onsubmit="return confirm('Delete this user? Their existing tickets will be retained.');"><?=csrf_field()?><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn danger small">Delete</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); exit; }
