if($page==='save_role' && $_SERVER['REQUEST_METHOD']==='POST') {
    $roleActor=require_permission('roles.manage'); require_permission('permissions.manage'); $id=(int)($_POST['id']??0); $name=strtolower(trim((string)($_POST['name']??'')));
    if(!preg_match('/^[a-z][a-z0-9_-]{1,39}$/',$name)){flash('Use a role name with 2–40 letters, numbers, underscores, or hyphens.','error');redirect(url('roles'));}
    try {
        $restricted=!is_admin($roleActor); $myKeys=effective_permissions($roleActor);
        if($id){ $oldRole=db()->prepare('SELECT name FROM roles WHERE id=?');$oldRole->execute([$id]);$oldName=(string)$oldRole->fetchColumn();
            if($oldName==='admin' && $restricted) throw new RuntimeException('Only a System Administrator can edit the admin role.');
            if($oldName==='admin' && $name!=='admin') throw new RuntimeException('The built-in admin role cannot be renamed.');
            db()->prepare('UPDATE roles SET name=? WHERE id=?')->execute([$name,$id]);
        } else db()->prepare('INSERT INTO roles(name) VALUES(?)')->execute([$name]);
        $rid=$id?:(int)db()->lastInsertId();
        $keepIds=[]; if($restricted && $id){ $kq=db()->prepare('SELECT p.id,p.permission_key FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=?'); $kq->execute([$rid]); foreach($kq->fetchAll() as $kr){ if(!in_array($kr['permission_key'],$myKeys,true)) $keepIds[]=(int)$kr['id']; } }
        db()->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$rid]);
        $permissionIds=array_map('intval',($_POST['permissions']??[]));
        if($name==='admin'){ $permissionIds=array_map('intval',db()->query('SELECT id FROM permissions')->fetchAll(PDO::FETCH_COLUMN)); }
        else { $permissionIds=array_values(array_filter($permissionIds,function($pid) use($restricted,$myKeys){ $q=db()->prepare('SELECT permission_key FROM permissions WHERE id=?'); $q->execute([(int)$pid]); $k=(string)$q->fetchColumn(); return $k!=='' && $k!=='admin.access' && (!$restricted || in_array($k,$myKeys,true)); })); $permissionIds=array_merge($permissionIds,$keepIds); }
        foreach(array_unique($permissionIds) as $pid) db()->prepare('INSERT OR IGNORE INTO role_permissions(role_id,permission_id) VALUES(?,?)')->execute([$rid,(int)$pid]);
        clear_permission_cache(); flash('Role saved.');
    } catch(Throwable $e) { flash($e instanceof RuntimeException?$e->getMessage():'Could not save role. Role names must be unique.','error'); }
    redirect(url('roles'));
}
if($page==='roles') { require_permission('roles.view');render_header('Roles and permissions',$u);$canEditRoles=has_permission('roles.manage',$u)&&has_permission('permissions.manage',$u);$editId=(int)($_GET['edit']??0);$edit=null;$selected=[];if($editId){$q=db()->prepare('SELECT * FROM roles WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;$q=db()->prepare('SELECT permission_id FROM role_permissions WHERE role_id=?');$q->execute([$editId]);$selected=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));} ?><?php if($canEditRoles): ?><div class="panel form-panel"><h2><?=$edit?'Edit role':'Create role'?></h2><form method="post" action="<?=url('save_role')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><label>Role name<input name="name" value="<?=h($edit['name']??'')?>" required></label><label>Permissions</label><p class="muted tiny">Permissions are additive across direct roles and group roles. The protected System Administrator role always retains full system access.</p><div class="member-checks"><?php foreach(db()->query("SELECT * FROM permissions WHERE permission_key<>'admin.access' OR (SELECT name FROM roles WHERE id=".(int)($edit['id']??0).")='admin' ORDER BY permission_key") as $perm): ?><label class="check"><input type="checkbox" name="permissions[]" value="<?=$perm['id']?>" <?=in_array((int)$perm['id'],$selected,true)?'checked':''?>> <?=h($perm['permission_key'])?> <small><?=h($perm['description'])?></small></label><?php endforeach; ?></div><button class="btn primary">Save role</button></form></div><?php endif; ?><div class="panel table-panel spaced"><table><thead><tr><th>Role</th><th>Permissions</th><th></th></tr></thead><tbody><?php foreach(db()->query('SELECT r.*,COUNT(rp.permission_id) permissions FROM roles r LEFT JOIN role_permissions rp ON rp.role_id=r.id GROUP BY r.id ORDER BY r.name') as $rr): ?><tr><td><?=h($rr['name'])?></td><td><?=$rr['permissions']?></td><td><?php if($canEditRoles): ?><a href="<?=url('roles',['edit'=>$rr['id']])?>">Edit</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer();exit;}
if(in_array($page,['reports','report_html','report_pdf'],true)) {
    $u=require_login(); if(!has_permission('reports.view_all',$u) && !has_permission('reports.view_group',$u) && !has_permission('tickets.view_all',$u)){http_response_code(403);exit('Forbidden');}
    $all=has_permission('reports.view_all',$u)||has_permission('tickets.view_all',$u); $from=(string)($_GET['from']??date('Y-m-01')); $to=(string)($_GET['to']??date('Y-m-d')); $group=(int)($_GET['group_id']??0);
    if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from) || !preg_match('/^\d{4}-\d{2}-\d{2}$/',$to) || $from>$to){flash('Choose a valid date range.','error');redirect(url('reports'));}
    $where=['substr(t.created_at,1,10)>=?','substr(t.created_at,1,10)<=?']; $params=[$from,$to];
    if($group>0){$where[]='t.group_id=?';$params[]=$group;}
    if(!$all){$scopeParts=['t.group_id IN (SELECT group_id FROM user_groups WHERE user_id=?)','t.assigned_user_id=?'];array_push($params,(int)$u['id'],(int)$u['id']);if(has_permission('tickets.view_own',$u)){$scopeParts[]='t.user_id=?';$params[]=(int)$u['id'];}$where[]='('.implode(' OR ',$scopeParts).')';}
    $sql='SELECT t.ticket_no,t.subject,t.created_at,t.updated_at,st.name status_name,p.name priority_name,g.name group_name,au.name assigned_name,COALESCE(t.guest_name,cu.name) requester_name FROM tickets t JOIN statuses st ON st.id=t.status_id JOIN priorities p ON p.id=t.priority_id LEFT JOIN groups g ON g.id=t.group_id LEFT JOIN users au ON au.id=t.assigned_user_id LEFT JOIN users cu ON cu.id=t.user_id WHERE '.implode(' AND ',$where).' ORDER BY t.created_at';
    $q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll(); $groups=[]; if($all){$groups=db()->query('SELECT id,name FROM groups ORDER BY name')->fetchAll();}else{$gq=db()->prepare('SELECT g.id,g.name FROM groups g JOIN user_groups ug ON ug.group_id=g.id WHERE ug.user_id=? ORDER BY g.name');$gq->execute([(int)$u['id']]);$groups=$gq->fetchAll();}
    if($page==='report_pdf') {
        $lines=['Period: '.$from.' through '.$to,'Tickets: '.count($rows),'']; foreach($rows as $r){$lines[]=$r['ticket_no'].' | '.substr($r['created_at'],0,10).' | '.$r['status_name'].' | '.$r['priority_name'];$lines[]='Subject: '.$r['subject'];$lines[]='Team: '.($r['group_name']??'Unassigned').' | Assigned: '.($r['assigned_name']??'Unassigned').' | Requester: '.($r['requester_name']??'');$lines[]='';}
        $pages=array_chunk($lines,48); if(!$pages)$pages=[['No tickets found for this date range.']]; $objects=[]; $objects[1]='<< /Type /Catalog /Pages 2 0 R >>'; $kids=[]; $fontId=3+count($pages)*2; foreach($pages as $i=>$pageLines){$pageId=3+$i*2;$contentId=$pageId+1;$kids[]=$pageId.' 0 R';$stream="BT\n/F1 9 Tf\n40 800 Td\n"; $title=$i===0?'HelpDesk Ticket Report':'HelpDesk Ticket Report (continued)';$stream.='('.str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$title).") Tj\n0 -18 Td\n";foreach($pageLines as $line){$line=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$line)?:'';$line=substr($line,0,115);$line=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$line);$stream.='('.$line.") Tj\n0 -14 Td\n";} $stream.="ET";$objects[$pageId]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 '.$fontId.' 0 R >> >> /Contents '.$contentId.' 0 R >>';$objects[$contentId]='<< /Length '.strlen($stream)." >>\nstream\n".$stream."\nendstream"; } $objects[2]='<< /Type /Pages /Kids ['.implode(' ',$kids).'] /Count '.count($pages).' >>';$objects[$fontId]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';ksort($objects);$pdf="%PDF-1.4\n";$offsets=[0];$max=max(array_keys($objects));for($i=1;$i<=$max;$i++){$offsets[$i]=strlen($pdf);$pdf.=$i." 0 obj\n".($objects[$i]??'<< >>')."\nendobj\n";} $xref=strlen($pdf);$pdf.="xref\n0 ".($max+1)."\n0000000000 65535 f \n";for($i=1;$i<=$max;$i++)$pdf.=sprintf('%010d 00000 n ',$offsets[$i])."\n";$pdf.="trailer\n<< /Size ".($max+1)." /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="helpdesk-ticket-report-'.$from.'-'.$to.'.pdf"');header('Content-Length: '.strlen($pdf));echo $pdf;exit;
    }
    if($page==='report_html') { header('Content-Type: text/html; charset=UTF-8'); ?><!doctype html><html><head><meta charset="utf-8"><title>HelpDesk Ticket Report</title><style>body{font:14px Arial,sans-serif;margin:30px;color:#222}h1{margin-bottom:4px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:8px;text-align:left}th{background:#eee}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print</button><h1><?=h(setting('app_name','HelpDesk'))?> Ticket Report</h1><p><?=h($from)?> through <?=h($to)?> · <?=count($rows)?> tickets</p><table><thead><tr><th>Ticket</th><th>Created</th><th>Subject</th><th>Status</th><th>Priority</th><th>Team</th><th>Assigned</th><th>Requester</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=h($r['ticket_no'])?></td><td><?=h(substr($r['created_at'],0,10))?></td><td><?=h($r['subject'])?></td><td><?=h($r['status_name'])?></td><td><?=h($r['priority_name'])?></td><td><?=h($r['group_name']??'Unassigned')?></td><td><?=h($r['assigned_name']??'Unassigned')?></td><td><?=h($r['requester_name']??'')?></td></tr><?php endforeach; ?></tbody></table></body></html><?php exit; }
