}

if($page==='settings') { require_permission('settings.manage'); render_header('Settings',$u); ?><?php if(!base_url_configured()): ?><div class="notice warning"><b>Public URL not set.</b> Email links are currently built from the request's host name. Set <code>base_url</code> in <code>config.php</code> (for example <code>https://support.example.com/helpdesk</code>) so links in emails cannot be influenced by a forged Host header.</div><?php endif; ?><?php $dbRel=db_relative_url(); if($dbRel!==''): ?><div class="notice error" id="db-exposure-warning" data-check-url="<?=h($dbRel)?>" hidden><b>Your database file appears to be downloadable from the web.</b> Block access to the <code>storage/</code> folder in your web server configuration (see INSTALL.md) or move the database outside the web root.</div><?php endif; ?><div class="settings-grid"><div class="panel form-panel"><h2>General settings</h2><form method="post" action="<?=url('save_settings')?>" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="section" value="general"><label>System name<input name="app_name" value="<?=h(setting('app_name','HelpDesk'))?>"></label><label>Theme<select name="theme"><option value="light" <?=setting('theme')==='light'?'selected':''?>>Light</option><option value="dark" <?=setting('theme')==='dark'?'selected':''?>>Dark</option></select></label><label class="check"><input type="checkbox" name="allow_guest" value="1" <?=setting('allow_guest')==='1'?'checked':''?>> Allow guest ticket submission</label><label>Brand primary color<input type="color" name="brand_color" value="<?=h(setting('brand_color','#12377b'))?>"></label><label>Company logo <small>(PNG, JPG, GIF, or WebP; subject to PHP/server upload limits)</small><input type="file" name="brand_logo_file" accept="image/png,image/jpeg,image/gif,image/webp"></label><?php if(setting('brand_logo','')!==''): ?><div class="logo-preview"><img src="<?=h(setting('brand_logo'))?>" alt="Current company logo" style="max-width:220px;max-height:90px"><label class="check"><input type="checkbox" name="remove_brand_logo" value="1"> Remove current logo</label></div><?php endif; ?><label>Contact email<input type="email" name="contact_email" value="<?=h(setting('contact_email',''))?>"></label><button class="btn primary">Save settings</button></form></div><div class="panel form-panel"><h2>Email notifications</h2><p class="muted">Uses PHP mail(). Your web server must have a working mail transfer agent configured.</p><form method="post" action="<?=url('save_settings')?>"><?=csrf_field()?><input type="hidden" name="section" value="email"><label>Sender name<input name="mail_from_name" value="<?=h(setting('mail_from_name',setting('app_name','HelpDesk')))?>"></label><label>Sender email<input type="email" name="mail_from" value="<?=h(setting('mail_from',''))?>"></label><label>Reply-to email<input type="email" name="reply_to" value="<?=h(setting('reply_to',''))?>"></label><label>Email footer<input name="email_footer" value="<?=h(setting('email_footer',''))?>"></label><?php foreach(['ticket_created'=>'New ticket submitted','ticket_assigned'=>'Ticket assigned','ticket_updated'=>'Ticket updated','ticket_resolved'=>'Ticket resolved'] as $k=>$label): ?><label class="check"><input type="checkbox" name="notify_<?=$k?>" value="1" <?=setting('notify_'.$k,'1')==='1'?'checked':''?>> <?=h($label)?></label><?php endforeach; ?><button class="btn primary">Save email settings</button></form><hr><h3>Ticket email templates</h3><p class="muted tiny">Available placeholders: {app_name}, {ticket_no}, {subject}, {status}, {message}, {customer_name}, and {{ticket.url}} (clickable ticket link). Legacy {ticket_url} is also supported. Use these templates for customer-facing ticket notifications.</p><form method="post" action="<?=url('save_settings')?>"><?=csrf_field()?><input type="hidden" name="section" value="templates"><?php foreach(['ticket_created'=>'New ticket confirmation','ticket_assigned'=>'Ticket assigned','ticket_updated'=>'Ticket updated','ticket_resolved'=>'Ticket resolved'] as $event=>$label): ?><h3><?=h($label)?></h3><label>Email subject<input name="template_<?=$event?>_subject" value="<?=h(setting('template_'.$event.'_subject',''))?>" placeholder="Use default subject"></label><div class="ph-bar" data-for="tpl_<?=$event?>_body"><span class="muted tiny">Insert placeholder:</span><?php foreach(['{customer_name}'=>'Customer name','{ticket_no}'=>'Ticket #','{subject}'=>'Subject','{status}'=>'Status','{message}'=>'Message','{app_name}'=>'System name','{{ticket.url}}'=>'Ticket link'] as $tok=>$lbl): ?><button type="button" class="chip" data-token="<?=h($tok)?>"><?=h($lbl)?></button><?php endforeach; ?></div><label>Email body<textarea id="tpl_<?=$event?>_body" class="rich-email-template" name="template_<?=$event?>_body" rows="8" placeholder="Leave blank to use the default template"><?=h(setting('template_'.$event.'_body',''))?></textarea></label><?php endforeach; ?><button class="btn primary">Save email templates</button></form><p class="muted tiny">The editor is Jodit (MIT licence). It loads from <code>public/vendor/jodit/</code> when present, otherwise from jsDelivr. If neither is reachable the fields remain editable as HTML textareas. Email HTML is sanitised again when it is sent.</p><hr><h3>Send test email</h3><form method="post" action="<?=url('test_mail')?>"><?=csrf_field()?><label>Recipient email<input type="email" name="test_email" placeholder="you@example.com" required></label><button class="btn secondary">Send test email</button></form></div></div><div class="panel form-panel spaced"><h2>Security</h2><form method="post" action="<?=url('save_settings')?>"><?=csrf_field()?><input type="hidden" name="section" value="security"><label class="check"><input type="checkbox" name="otp_enabled" value="1" <?=otp_enabled()?'checked':''?>> Require email one-time codes for logins, new registrations, and guest ticket submissions</label><label>Remember verified users for (days)<input type="number" name="otp_remember_days" min="1" max="30" value="<?=h(setting('otp_remember_days','5'))?>" required></label><label>Failed sign-in attempts before a temporary lock<input type="number" name="login_max_attempts" min="3" max="20" value="<?=h(setting('login_max_attempts','5'))?>" required></label><label>Lockout window (minutes)<input type="number" name="login_lockout_minutes" min="1" max="240" value="<?=h(setting('login_lockout_minutes','15'))?>" required></label><p class="muted tiny">Verified users will not be asked for another code until they have been inactive for this many days (maximum 30). New or not-yet-verified accounts must verify first. Codes expire after 10 minutes, allow five attempts, and can be resent after 60 seconds.</p><button class="btn primary">Save security settings</button></form></div><div class="panel form-panel spaced"><h2>System information</h2><div class="info-grid"><div><small>Software version</small><b><?=h(app_version())?></b></div><div><small>PHP version</small><b><?=h(PHP_VERSION)?></b></div><div><small>Database</small><b>SQLite / PDO</b></div><div><small>Schema version</small><b><?=h(setting('schema_version','0'))?></b></div><div><small>Public URL (base_url)</small><b><?=base_url_configured()?'Configured':'Not set'?></b></div><div><small>Mail transport</small><b>PHP mail()</b></div><div><small>PHP upload_max_filesize</small><b><?=h((string)ini_get('upload_max_filesize'))?></b></div><div><small>PHP post_max_size</small><b><?=h((string)ini_get('post_max_size'))?></b></div><div><small>PHP max_file_uploads</small><b><?=h((string)ini_get('max_file_uploads'))?></b></div></div><p class="muted tiny">LDAP and SSO are reserved for a future authentication-provider module. Back up storage/helpdesk.sqlite and uploads/ regularly.</p></div><?php render_footer(); exit; }
